-- Train Tycoon MVP scenario. The map is generated by the mod (remote "tt-map") so the same
-- layout can be built by tests.
script.on_init(function()
  remote.call("tt-map", "generate")
end)

script.on_event(defines.events.on_player_created, function(e)
  remote.call("tt-map", "setup_player", e.player_index)
  local player = game.get_player(e.player_index)
  if player then player.print({ "tt-scenario.welcome" }) end
end)
